interface Invoice {
  readonly id: string;     // nur lesbar, nach dem Anlegen nicht änderbar
  customerId: string;
  note?: string;           // optional, darf fehlen
}

const invoice: Invoice = { id: "R-1", customerId: "1" };
invoice.note = "bezahlt";  // erlaubt
// invoice.id = "R-2";     // Fehler TS2540: id ist readonly

const ids: readonly string[] = ["1", "2"];
// ids.push("3");          // Fehler: Eine readonly-Liste hat kein push
const more = [...ids, "3"];  // neue Liste ist erlaubt

const [first, , third] = customers;      // Liste zerlegen, zweiten überspringen

const { firstname, lastname } = first;   // Objekt zerlegen
const { city = "unbekannt" } = third;    // Standardwert, falls city fehlt
const { id, ...rest } = first;           // rest: alle übrigen Eigenschaften

// Zerlegen direkt in der Parameterliste
function label({ firstname, lastname }: Customer): string {
  return `${lastname}, ${firstname}`;
