type CustomerChanges = Partial<Customer>;       // alles optional
type CustomerName = Pick<Customer, "firstname" | "lastname">;  // nur diese
type NewCustomer = Omit<Customer, "id">;        // alles außer id

function update(c: Customer, changes: Partial<Customer>): Customer {
  return { ...c, ...changes };
}

const changed = update(customers[0], { city: "Shelbyville" });
const draft: NewCustomer = { firstname: "Ned", lastname: "Flanders" };
const label: CustomerName = changed;     // Customer hat diese Felder auch

